15	/**
16	 * This analyzer limits the highlighting once it sees a token with a start offset &lt;= the configured limit,
17	 * which won't pass and will end the stream.
18	 * @see LimitTokenOffsetFilter
19	 */
20	public final class LimitTokenOffsetAnalyzer extends AnalyzerWrapper {
21	
22	    private final Analyzer delegate;
23	    private final int maxOffset;
24	
25	    /**
26	     * Build an analyzer that limits the highlighting once it sees a token with a start offset &lt;= the configured limit,
27	     * which won't pass and will end the stream. See {@link LimitTokenOffsetFilter} for more details.
28	     *
29	     * @param delegate the analyzer to wrap
30	     * @param maxOffset max number of tokens to produce
31	     */
32	    public LimitTokenOffsetAnalyzer(Analyzer delegate, int maxOffset) {
33	        super(delegate.getReuseStrategy());
34	        this.delegate = delegate;
35	        this.maxOffset = maxOffset;
36	    }
37	
38	    @Override
39	    protected Analyzer getWrappedAnalyzer(String fieldName) {
40	        return delegate;
41	    }
42	
43	    @Override
44	    protected TokenStreamComponents wrapComponents(String fieldName, TokenStreamComponents components) {
45	        return new TokenStreamComponents(components.getSource(), new LimitTokenOffsetFilter(components.getTokenStream(), maxOffset, false));
46	    }
47	
48	    @Override
49	    public String toString() {
50	        return "LimitTokenOffsetAnalyzer(" + delegate.toString() + ", maxOffset=" + maxOffset + ")";
